PHOTOS_AJOUTEES.forEach((p,i)=>{const id="ajout"+i;IM[id]=TH[id]=p.fichier;(PH[p.pays]=PH[p.pays]||[]).push([id,p.legende[0],p.legende[1]||p.legende[0],p.cadrage||"50% 50%"]);p.id=id});
