const IMG={judo:"images/activites/judo-cours-sm.jpg",boxe:"images/activites/boxe-gants-sm.jpg",foot:"images/activites/football-terrain-sm.jpg",tennis:"images/activites/tennis-balle-sm.jpg"};
const A=[["boxe","","Boxe","J’ai pratiqué deux ans de boxe anglaise au sein du club CAM à Bordeaux. Ce sport m’a instruit beaucoup de valeurs que je considère très importantes dans le métier d’ingénieur : le <b>respect</b>, <b>l’assiduité</b>, <b>l’humilité</b> et la <b>détermination</b>. Il m’a beaucoup manqué pendant ma classe préparatoire, j’ai donc décidé de reprendre des cours au sein de l’association de l’ENSEEIHT."],
["surf","","Surf","Je fais du surf depuis mon enfance grâce à mon père qui m’a transmis sa passion. Habitant à Bordeaux avant d’arriver à Toulouse, j’ai énormément surfé sur la côte atlantique, seul ou avec mon cousin (Montalivet, Lacanau…). J’ai aussi eu la chance de surfer dans d’autres pays au cours de mes voyages, comme le Panama, le Maroc (Essaouira, Sidi Kaouki) et le Portugal."],
["batterie","ct","Batterie","J’ai suivi des cours de batterie pendant 8 ans dans l’école de musique « Jouer sur les cordes ». J’ai pu réaliser un grand nombre de concerts, que ce soit sur des scènes (Rockschool Barbey) pour des événements particuliers comme la fête de la musique, ou dans des maisons de retraite (EHPAD) pour reprendre des classiques de la chanson française et toucher un public différent. Cette expérience m’a permis d’apprendre à <b>gérer mon stress</b> devant un grand public, de développer une meilleure <b>rigueur</b> et un bon <b>esprit d’équipe</b>."],
["foot","ct","Football","J’ai commencé le foot en primaire dans un club nommé l’ASPTT Stade Bordelais jusqu’à l’âge de 13 ans. J’ai appris à évoluer et à me faire ma place au sein d’un <b>collectif</b>. Durant les matchs, on apprend à communiquer sous la pression, à jouer en équipe plutôt que seul et à faire preuve d’un véritable esprit d’équipe pour gagner le match. Après mon expérience en club, j’ai continué à jouer au foot de temps en temps, jusqu’à mon arrivée à Toulouse où je me suis inscrit à l’AS foot des INP Toulouse."],
["tennis","","Tennis","J’ai pratiqué le tennis pendant cinq ans en club au CAM de Bordeaux. Ce sport m’a appris à développer ma concentration, ma persévérance et ma maîtrise du mental, notamment dans les moments difficiles où il faut savoir garder son calme pour ne pas craquer. J’ai aussi eu l’opportunité de faire ramasseur de balle lors de plusieurs tournois professionnels organisés par mon club."],
["judo","","Judo","J’ai pratiqué le judo pendant cinq ans au sein de mon école primaire, jusqu’à l’obtention de ma ceinture orange. Cette première expérience dans les sports de combat m’a permis d’apprendre les bases de la discipline, de maîtriser mes premières prises et d’apprendre à chuter en sécurité.\n\nJ’ai envisagé de reprendre le judo au lycée, avant de finalement m’orienter vers la boxe, tout en gardant un bon souvenir de cette première découverte des sports de combat.","50% 38%"]];
const ALT={surf:["Surfeur sur une vague","Surfer riding a wave"],"surf-maroc-marche":["Deux surfeurs en poncho marchant vers la plage, planches sous le bras","Two surfers in ponchos walking to the beach with their boards"],"football-terrain":["Edgar enfant en tenue de football sur un terrain synthétique","Edgar as a child in football kit on an artificial pitch"],"football-match":["Match de football entre jeunes joueurs","Youth football match"],"football-girondins":["Jeunes joueurs posant avec l’équipe des Girondins de Bordeaux","Young players posing with the Girondins de Bordeaux team"],"boxe-gants":["Paire de gants de boxe blancs posés sur le bord d’un ring","Pair of white boxing gloves resting on the edge of a ring"],"tennis-balle":["Balle de tennis rebondissant sur la ligne d’un court en terre battue","Tennis ball bouncing on the line of a clay court"],"judo-cours":["Deux enfants en kimono avec une ceinture jaune pendant un cours de judo","Two children in judo uniforms with yellow belts during a class"],"panama-surf":["Surfeur sur une vague au Panama","Surfer riding a wave in Panama"],"surf-enfance":["Enfant allongé sur une planche de surf dans les vagues","Child lying on a surfboard in the waves"],batterie:["Batteur jouant sur scène","Drummer playing on stage"],judo:["Illustration : ceinture orange de judo nouée","Illustration: tied orange judo belt"],tennis:["Illustration : raquette et balle de tennis","Illustration: tennis racket and ball"],boxe:["Illustration : paire de gants de boxe","Illustration: pair of boxing gloves"],foot:["Logo du club ASPTT Stade Bordelais","ASPTT Stade Bordelais club logo"]};
