function setLang(en){EN=en;try{localStorage.setItem("lang",en?"en":"fr")}catch(e){}document.documentElement.lang=en?"en":"fr";document.getElementById("pvid").setAttribute("aria-label",en?"Edgar Lapouge’s elevator speech (video, 3 min 11 s)":"Elevator speech d’Edgar Lapouge (vidéo, 3 min 11 s)");OR.forEach((h,e)=>{if(e.isConnected)e.innerHTML=h});OR.clear();renderM();mapLang();renderA();showE(curI);setCV(en?"en":"fr");tr();lgb.textContent=en?"FR":"EN";lgb.setAttribute("lang",en?"fr":"en");lgb.setAttribute("aria-label",en?"Version française":"English version");[["#lb .x","Fermer","Close"],["#lb .pv","Photo précédente","Previous photo"],["#lb .nx","Photo suivante","Next photo"]].forEach(([q,f,g])=>document.querySelector(q).setAttribute("aria-label",en?g:f));document.getElementById("lb").setAttribute("aria-label",en?"Photo viewer":"Visionneuse de photos");document.querySelector(".skip").textContent=en?"Skip to content":"Aller au contenu";document.querySelector("nav").setAttribute("aria-label",en?"Main navigation":"Navigation principale");document.querySelectorAll(".rv").forEach(x=>x.classList.add("on"))}
