document.addEventListener("click",async e=>{const b=e.target.closest(".mcopy");if(!b)return;const t=b.dataset.copy,sp=b.querySelector("span");try{await navigator.clipboard.writeText(t);sp.textContent=EN?"Address copied":"Adresse copiée"}catch(x){const a=b.closest(".card").querySelector(".maddr"),r=document.createRange();r.selectNodeContents(a);const se=getSelection();se.removeAllRanges();se.addRange(r);sp.textContent=EN?"Address selected, copy it":"Adresse sélectionnée, copiez-la"}setTimeout(()=>{sp.textContent=EN?"Copy the address":"Copier l’adresse"},2600)});
